  "Cisco_Billing_Term": "Prepaid Term",
  "Billing_Street": "{from Account or lookup}",
  "Billing_City": "{from Account or lookup}",
  "Billing_State": "{2-LETTER CODE}",
  "Billing_Code": "{zip}",
  "Billing_Country": "US",
  "Shipping_Country": "US",
  "Owner": {"id": "{{OWNER_ZOHO_ID}}"},
