// ═══════════════════════════════════════════════════════════════════════════════
// Phase 1: Most-recent-quote session header helpers
// ═══════════════════════════════════════════════════════════════════════════════
// Shared between /api/chat and /api/chat-waterfall (gateway path). Scans the
// conversation history for the most recently mentioned Zoho Quote, returns a
// {recordId, quoteNumber} pair if found. The session header tells the model
// which quote "the quote" / "that quote" refers to on a follow-up turn — this
// is the grounding fix for the Electrocraft 148/151 mismatch class of bugs.
//
// MODULE-SCOPED on the extension side (ChatPanel.jsx buildZohoPageContextHint):
// the active page hint no longer claims an Account/Deal record IS a quote.
// The session header is the authoritative source for "the quote" on
// Account-context follow-ups.
// ═══════════════════════════════════════════════════════════════════════════════
function extractMostRecentQuoteRefFromHistory(history) {
  if (!Array.isArray(history) || history.length === 0) return null;
  for (let i = history.length - 1; i >= 0; i--) {
    const msg = history[i];
    if (!msg || msg.role !== 'assistant') continue;
    const content = typeof msg.content === 'string'
      ? msg.content
      : (msg.content ? JSON.stringify(msg.content) : '');
    if (!content) continue;
    // Match Zoho Quote URLs: https://crm.zoho.com/crm/org{N}/tab/Quotes/{id}
    const urlMatch = content.match(/crm\.zoho\.com\/crm\/org\d+\/tab\/Quotes\/(\d+)/);
    // Match 14+ digit record id near "Quote" (e.g. "Quote 2570562000404932151")
    const numMatch = content.match(/Quote[:\s#]+(\d{14,})/i);
    // Match Zoho Quote_Number (typically "QU-..." or numeric short form near "Quote_Number")
    const quoteNumMatch = content.match(/Quote_Number[:\s]+(QU-[A-Z0-9-]+|\d{5,})/i);
    if (urlMatch || numMatch || quoteNumMatch) {
      return {
        recordId: urlMatch ? urlMatch[1] : (numMatch ? numMatch[1] : null),
        quoteNumber: quoteNumMatch ? quoteNumMatch[1] : null
      };
    }
  }
  return null;
}

function buildMostRecentQuoteSessionHeader(history) {
  const ref = extractMostRecentQuoteRefFromHistory(history);
  if (!ref || (!ref.recordId && !ref.quoteNumber)) return '';
  const parts = [];
  if (ref.quoteNumber) parts.push(`Quote_Number: ${ref.quoteNumber}`);
  if (ref.recordId) parts.push(`Record_ID: ${ref.recordId} — URL: https://crm.zoho.com/crm/org647122552/tab/Quotes/${ref.recordId}`);
  return `[Session: Most recently worked quote — ${parts.join(', ')}. When user says "the quote", "that quote", or "same quote" without specifying another, use THIS quote. Do NOT ask which quote. An active Account or Deal page is parent/customer context, not "the quote" — defer to THIS session quote on quote-specific follow-ups.]`;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Cloudflare Workflow: Durable CRM Execution
// ═══════════════════════════════════════════════════════════════════════════════
// Replaces Queue-based CRM dispatch with per-step retries and durable state.
// Each step is independently retriable — if Zoho times out, only that step
// re-runs, not the entire agentic loop.
//
// Dispatch priority: CRM_WORKFLOW → CRM_QUEUE → ctx.waitUntil
// ═══════════════════════════════════════════════════════════════════════════════
export class CrmWorkflow extends WorkflowEntrypoint {
  async run(event, step) {
    const { text, personId, spaceName, threadName, imageDataKey } = event.payload;

    if (!spaceName) {
      throw new Error('[WORKFLOW] No spaceName in payload — cannot deliver response');
    }

    const env = this.env;
    const workflowStart = Date.now();
    console.log(`[WORKFLOW] Starting CRM workflow for: "${(text || '').substring(0, 80)}..."`);

    // Step 1: Load live prices from shared KV
    await step.do('load-prices', async () => {
      if (env.CONVERSATION_KV) {
        await loadLivePrices(env);
      }
      return true;
    });

    // Step 2: Send "Working on it..." progress message
    const progressMsgName = await step.do('send-progress',
      { retries: { limit: 2, delay: '2 seconds' } },
      async () => {
        try {
          const msg = await sendAsyncGChatMessage(spaceName, '⏳ Working on it...', null, env);
          return msg?.name || null;
        } catch (err) {
          console.error(`[WORKFLOW] Failed to send progress: ${err.message}`);
          return null; // Non-fatal: proceed without progress updates
        }
      }
    );

    // Step 3: Run the CRM agentic loop (main work)
    // This is the heavy step — askClaude may make multiple Zoho + Anthropic calls.
    // Timeout: 5 minutes. Retry once on failure (covers transient API errors).
    const result = await step.do('process-crm',
      { retries: { limit: 1, delay: '5 seconds' }, timeout: '5 minutes' },
      async () => {
        // Reload live prices in case this step was retried (module state is lost on retry)
        if (env.CONVERSATION_KV) await loadLivePrices(env);

        // Retrieve image data from KV if the caller stored it there
        let imageData = null;
        if (imageDataKey) {
          try {
            imageData = await env.CONVERSATION_KV.get(imageDataKey, 'json');
            await env.CONVERSATION_KV.delete(imageDataKey); // Clean up temp key
          } catch (_) {}
        }

        // Progress callback: update the "Working on it..." message with step details
        let _stepLog = [];
        const progressCallback = progressMsgName
          ? async (stepMsg) => {
              if (!stepMsg) return;
              const lines = stepMsg.split('\n').filter(l => /^[🔍📄🔗✏️📦🌐📧✍️📤⚙️]/.test(l.trim()));
              for (const line of lines) {
                const trimmed = line.trim();
                if (_stepLog.length === 0 || _stepLog[_stepLog.length - 1] !== trimmed) {
                  _stepLog.push(trimmed);
                }
              }
              const recentSteps = _stepLog.slice(-5);
              const display = recentSteps.length > 0
                ? `⏳ *Working on it...*\n\n${recentSteps.join('\n')}`
                : '⏳ Working on it...';
              try { await updateGChatMessage(progressMsgName, display, env); } catch (_) {}
            }
          : async () => {};

        const reply = await askClaude(text, personId, env, imageData, true, progressCallback, 300000);
        let finalReply = typeof reply === 'string' ? reply : (reply?.reply || 'Done.');
        finalReply = adaptMarkdownForGChat(finalReply);
        finalReply = truncateGChatReply(finalReply);
        return finalReply;
      }
    );

    // Step 4: Deliver final response to Google Chat
    await step.do('deliver-response',
      { retries: { limit: 3, delay: '2 seconds', backoff: 'linear' } },
      async () => {
        let delivered = false;
        if (progressMsgName) {
          try {
            delivered = await updateGChatMessage(progressMsgName, result, env);
            if (delivered) console.log(`[WORKFLOW] Final response PATCH'd onto ${progressMsgName}`);
          } catch (patchErr) {
            console.warn(`[WORKFLOW] PATCH failed: ${patchErr.message}`);
          }
        }
        if (!delivered) {
          await sendAsyncGChatMessage(spaceName, result, null, env);
        }
        return delivered;
      }
    );

    // Step 5: Update conversation history in KV
    await step.do('update-history',
      { retries: { limit: 2, delay: '1 second' } },
      async () => {
        const kv = env.CONVERSATION_KV;
        if (personId && kv) {
          await addToHistory(kv, personId, 'user', text);
          await addToHistory(kv, personId, 'assistant', result);
          await kv.put(`crm_session_${personId}`, 'active', { expirationTtl: 600 });
        }
        return true;
      }
    );

    console.log(`[WORKFLOW] Completed in ${Date.now() - workflowStart}ms`);
    return { success: true, spaceName, textLength: result?.length || 0 };
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// Phase 3 (2026-05-12) — QuotePoWorkflow: durable quote→DID→PO→e-sign
// ═══════════════════════════════════════════════════════════════════════════════
// Wraps the existing synchronous handleQuoteToPoAndEsign orchestrator in a
// Cloudflare Workflow so:
//   - Execution survives the in-request wall-clock cap (workflows run on a
//     separate isolate with per-step retry & sleep semantics).
//   - The starter tool can return immediately on slow Cisco days while the
//     workflow keeps running, then the user (via the model) polls status via
//     `quote_to_po_status(workflow_id)`.
//   - Failures are logged once per terminal state in D1.quote_po_workflow_runs
//     for diagnostic visibility.
//
// Kill switch: env.QUOTE_PO_WORKFLOW_ENABLED.
//   - "true" / true / "1" → use the workflow path
//   - anything else (default) → fall back to inline synchronous execution
//     (identical to pre-Phase-3 behavior)
// Flip without redeploy:
//   wrangler secret put QUOTE_PO_WORKFLOW_ENABLED --name stratus-ai-bot-gchat
//
// MVP scope: single step.do wrapping handleQuoteToPoAndEsign. Worst-case 322s
// fits inside the 5-minute step ceiling on happy paths. Future split into
// per-action steps (DID / convert / esign) for true per-step retry is queued.
//
// NO advisor() call inside the workflow — failed-closed payloads only.
// ═══════════════════════════════════════════════════════════════════════════════

const QUOTE_PO_WORKFLOW_STATUS_TTL = 86400; // 24h KV TTL for status records

function isQuotePoWorkflowEnabled(env) {
  const v = env?.QUOTE_PO_WORKFLOW_ENABLED;
  return v === true || v === 'true' || v === '1';
}

async function writeQuotePoStatus(env, workflowId, payload) {
  if (!env?.CONVERSATION_KV || !workflowId) return;
  try {
    const record = { ...payload, updated_at: Date.now() };
    await env.CONVERSATION_KV.put(
      `quote_po_workflow:${workflowId}`,
      JSON.stringify(record),
      { expirationTtl: QUOTE_PO_WORKFLOW_STATUS_TTL }
    );
  } catch (err) {
    console.log(`[QPO-KV] writeQuotePoStatus skipped: ${err.message}`);
  }
}

async function readQuotePoStatus(env, workflowId) {
  if (!env?.CONVERSATION_KV || !workflowId) return null;
  try {
    return await env.CONVERSATION_KV.get(`quote_po_workflow:${workflowId}`, 'json');
  } catch (err) {
    console.log(`[QPO-KV] readQuotePoStatus error: ${err.message}`);
    return null;
  }
}

async function logQuotePoWorkflowRun(env, {
  workflow_id, quote_id, person_id, status, error_message, duration_ms,
  result, caller_source
}) {
  if (!env?.ANALYTICS_DB) return;
  try {
    const resultSummary = result
      ? JSON.stringify({
          success: !!result.success,
          state: result.state || null,
          sales_order_id: result.sales_order?.id || result.sales_order_id || null,
          error: result.error || null
        }).substring(0, 4000)
      : null;
    const salesOrderId = result?.sales_order?.id || result?.sales_order_id || null;
    const createdPo = result?.sales_order?.id ? 1 : 0;
    const esignSent = result?.esign_admin_action?.success || result?._user_visible_summary?.toLowerCase?.()?.includes?.('sent for e-signature') ? 1 : 0;
    await env.ANALYTICS_DB.prepare(
      `INSERT INTO quote_po_workflow_runs (
        workflow_id, quote_id, person_id, status, error_message, duration_ms,
        result_summary, sales_order_id, created_po, esign_sent, caller_source, created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      workflow_id || null,
      quote_id || null,
      person_id || null,
      status || 'unknown',
      error_message || null,
      duration_ms || null,
      resultSummary,
      salesOrderId,
      createdPo,
      esignSent,
      caller_source || null,
      new Date().toISOString()
    ).run();
  } catch (err) {
    console.log(`[QPO-D1] logQuotePoWorkflowRun skipped: ${err.message}`);
  }
}

export class QuotePoWorkflow extends WorkflowEntrypoint {
  async run(event, step) {
    const env = this.env;
    const payload = event?.payload || {};
    const workflowId = payload.workflow_id;
    const quoteId = payload.quote_id;
    const personId = payload.person_id || 'workflow-system';
    const callerSource = payload.caller_source || null;
    const t0 = payload._t0 || Date.now();

    if (!workflowId || !quoteId) {
      throw new Error(`[QPO-WORKFLOW] missing workflow_id or quote_id (got workflow_id=${workflowId}, quote_id=${quoteId})`);
    }

    console.log(`[QPO-WORKFLOW] Starting workflow_id=${workflowId} quote_id=${quoteId}`);

    await writeQuotePoStatus(env, workflowId, {
      state: 'running',
      step: 'execute',
      quote_id: quoteId,
      person_id: personId,
      started_at: t0
    });

    let result;
    try {
      result = await step.do('execute',
        { retries: { limit: 1, delay: '10 seconds' }, timeout: '5 minutes' },
        async () => {
          // Module state is lost across step retries; reload prices defensively.
          if (env.CONVERSATION_KV) {
            try { await loadLivePrices(env); } catch (_) {}
          }
          return await handleQuoteToPoAndEsign(
            {
              quote_id: quoteId,
              send_for_esign: payload.send_for_esign !== false,
              force_create_po: payload.force_create_po === true,
              sales_order_id: payload.sales_order_id || null
            },
            env,
            personId
          );
        }
      );
    } catch (stepErr) {
      const errMsg = stepErr?.message || String(stepErr);
      console.error(`[QPO-WORKFLOW] step.do threw: ${errMsg}`);
      await writeQuotePoStatus(env, workflowId, {
        state: 'terminal',
        success: false,
        error: errMsg,
        completed_at: Date.now()
      });
      await logQuotePoWorkflowRun(env, {
        workflow_id: workflowId,
        quote_id: quoteId,
        person_id: personId,
        status: 'error',
        error_message: errMsg,
        duration_ms: Date.now() - t0,
        caller_source: callerSource
      });
      throw stepErr;
    }

    await writeQuotePoStatus(env, workflowId, {
      state: 'terminal',
      success: !!result?.success,
      result,
      completed_at: Date.now()
    });

    await logQuotePoWorkflowRun(env, {
      workflow_id: workflowId,
      quote_id: quoteId,
      person_id: personId,
      status: result?.success ? 'success' : 'error',
      error_message: result?.error || null,
      duration_ms: Date.now() - t0,
      result,
      caller_source: callerSource
    });

    console.log(`[QPO-WORKFLOW] Completed workflow_id=${workflowId} success=${!!result?.success} duration=${Date.now() - t0}ms`);
    return result;
  }
}

// Hybrid sync/async wait wrapper. Triggers QuotePoWorkflow then blocks on
// KV-based status polling for a caller-aware window. Falls back to inline
// synchronous execution when the kill switch is off, the binding is missing,
// or workflow create() fails.
async function handleQuoteToPoAndEsignViaWorkflow(toolInput, env, personId) {
  const quoteId = toolInput?.quote_id;
  if (!quoteId) {
    return { success: false, error: 'quote_id is required', _no_partial_success: true };
  }

  // Kill switch — when disabled, behave exactly like before Phase 3.
  if (!isQuotePoWorkflowEnabled(env)) {
    return await handleQuoteToPoAndEsign(toolInput, env, personId);
  }

  if (!env?.QUOTE_PO_WORKFLOW || typeof env.QUOTE_PO_WORKFLOW.create !== 'function') {
    console.log('[QPO] QUOTE_PO_WORKFLOW binding missing; falling back to inline');
    return await handleQuoteToPoAndEsign(toolInput, env, personId);
  }

  // Source-aware wait window. Async-capable callers can hold longer; sync
  // HTTP callers (extension /api/chat, /api/chat-waterfall) need a tighter
  // budget so the HTTP response doesn't time out before we return.
  const callerSource = env.__CALLER_SOURCE || 'unknown';
  const waitMs = (callerSource === 'gchat' || callerSource === 'workflow' || callerSource === 'async')
    ? 150000
    : 95000;

  let workflowId;
  try {
    workflowId = crypto.randomUUID();
  } catch (_) {
    workflowId = `qpo-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
  }
  const t0 = Date.now();

  // Pre-seed KV with 'queued' so a status poll between create() and the
  // workflow's first KV write returns coherent state.
  await writeQuotePoStatus(env, workflowId, {
    state: 'queued',
    quote_id: quoteId,
    person_id: personId,
    started_at: t0
  });

  try {
    await env.QUOTE_PO_WORKFLOW.create({
      params: {
        workflow_id: workflowId,
        quote_id: quoteId,
        send_for_esign: toolInput.send_for_esign !== false,
        force_create_po: toolInput.force_create_po === true,
        sales_order_id: toolInput.sales_order_id || null,
        person_id: personId,
        caller_source: callerSource,
        _t0: t0
      }
    });
  } catch (createErr) {
    console.log(`[QPO] Workflow create failed (${createErr.message}); falling back to inline`);
    // Log the fall-back so we can spot binding/permission issues.
    await logQuotePoWorkflowRun(env, {
      workflow_id: workflowId,
      quote_id: quoteId,
      person_id: personId,
      status: 'error',
      error_message: `workflow_create_failed: ${createErr.message}`,
      duration_ms: Date.now() - t0,
      caller_source: callerSource
    });
    return await handleQuoteToPoAndEsign(toolInput, env, personId);
  }

  // Poll KV for status until the workflow terminates or we hit the wait deadline.
  const deadline = Date.now() + waitMs;
  const pollIntervalMs = 2500;
  let lastStatus = null;
  while (Date.now() < deadline) {
    await sleep(pollIntervalMs);
    lastStatus = await readQuotePoStatus(env, workflowId);
    if (lastStatus?.state === 'terminal') {
      const result = lastStatus.result || {
        success: !!lastStatus.success,
        error: lastStatus.error
      };
      return {
        ...result,
        _workflow: {
          workflow_id: workflowId,
          mode: 'completed_in_window',
          wall_ms: Date.now() - t0
        }
      };
    }
  }

  // Wait window expired; workflow is still running in the background.
  return {
    success: false,
    state: 'in_progress',
    workflow_id: workflowId,
    quote_id: quoteId,
    current_step: lastStatus?.step || 'running',
    started_at: t0,
    wall_ms: Date.now() - t0,
    next_action: `quote_to_po_status with workflow_id="${workflowId}"`,
    _user_visible_summary: `Quote-to-PO workflow started (id ${workflowId.substring(0, 8)}...). It is still running in the background. I'll check back in 1–2 minutes — or you can ask "status of that workflow" any time.`
  };
}

async function handleQuotePoStatus(toolInput, env, personId) {
  const workflowId = toolInput?.workflow_id;
  if (!workflowId) {
    return { success: false, error: 'workflow_id is required' };
  }
  const status = await readQuotePoStatus(env, workflowId);
  if (!status) {
    return {
      success: false,
      workflow_id: workflowId,
      state: 'not_found',
      error: 'Workflow id not found. It may have expired (24h KV TTL) or the create() call failed.'
    };
  }
  if (status.state === 'terminal') {
    const result = status.result || { success: !!status.success, error: status.error };
    return {
      success: !!result.success,
      workflow_id: workflowId,
      state: 'terminal',
      completed_at: status.completed_at || null,
      ...result
    };
  }
  return {
    success: false,
    workflow_id: workflowId,
    state: status.state || 'running',
    step: status.step || null,
    started_at: status.started_at || null,
    updated_at: status.updated_at || null
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// A/B MODEL BENCHMARK INFRASTRUCTURE
// Compares Claude vs Cloudflare Workers AI models on CRM tool-use tasks.
// Supports dry-run mode: reads hit real CRM, writes are mocked.
// ═══════════════════════════════════════════════════════════════════════════

// Tools that WRITE to Zoho/Gmail/Webex — mocked in dry-run mode
const BENCHMARK_WRITE_TOOLS = new Set([
  'zoho_create_record',
  'zoho_update_record',
  'zoho_delete_record',
  'clone_quote',
  'create_deal_and_quote',
  'create_quote_on_deal',
  'quote_to_po_and_esign',
  'velocity_hub_submit',
  'assign_cisco_rep_to_deal',
  'gmail_create_draft',
  'gmail_send_email',
  'webex_send_message',
  'zoho_create_note',
  'zoho_update_note',
  'undo_crm_action'
]);

// Tools that READ — always execute against real CRM
const BENCHMARK_READ_TOOLS = new Set([
  'zoho_search_records',
  'zoho_get_record',
  'zoho_get_related_records',
  'zoho_get_field',
  'zoho_coql_query',
  'batch_product_lookup',
  'gmail_search_messages',
  'gmail_read_message',
  'gmail_read_thread',
  'parse_quote_url',
  'web_search_domain',
  'build_quote_url',
  'quote_to_po_status'
]);

// Wrapper for executeToolCall that mocks writes in dry-run mode.
// Returns { result, mocked, payloadPreview }.
async function executeToolCallDryRun(toolName, toolInput, env, personId, dryRun) {
  if (dryRun && BENCHMARK_WRITE_TOOLS.has(toolName)) {
    // ── Universal correctness preflight (runs BEFORE dry-run mock) ──
    // Without this, CF-model dry-run tests mock a SUCCESS response even when
    // the model fabricated a product_id, giving false-positive benchmark passes.
    // Live production catches this via the preflight inside executeToolCall's
    // switch-case, but that path is bypassed when the dry-run mock fires first.
    try {
      if (toolName === 'zoho_update_record' || toolName === 'zoho_create_record') {
        const items = toolInput?.data?.Quoted_Items || toolInput?.recordData?.Quoted_Items;
        const isQuotesModule = toolInput?.module_name === 'Quotes';
        if (isQuotesModule && Array.isArray(items)) {
          const activeCheck = preflightQuotedItemsProductActive(items);
          if (!activeCheck.valid) {
            const hasHallucination = activeCheck.hallucinated_ids && activeCheck.hallucinated_ids.length > 0;
            const blockAction = toolName === 'zoho_update_record' ? 'update_blocked' : 'create_blocked';
            return {
              result: {
                validation_error: true,
                action: blockAction,
                message: hasHallucination
                  ? `Cannot add line item(s) to quote:\n${activeCheck.errors.join('\n')}`
                  : `EOL SKU detected — cannot add to quote:\n${activeCheck.errors.join('\n')}`,
                blocked_items: activeCheck.blocked_items,
                hallucinated_ids: activeCheck.hallucinated_ids
              },
              mocked: true,
              payloadPreview: JSON.stringify(toolInput).substring(0, 500)
            };
          }
        }
      }
    } catch (e) {
      console.log(`[PREFLIGHT-DRYRUN] pre-mock check threw: ${e.message}`);
    }

    // ── Truncated record_id preflight (dry-run path) ──
    // Without this, dry-run mocks return SUCCESS with a truncated id,
    // which Llama then embeds in the user-facing View URL → broken link.
    try {
      const idBearingWriteTools = new Set(['zoho_update_record', 'zoho_delete_record']);
      if (idBearingWriteTools.has(toolName)) {
        const rid = toolInput?.record_id;
        if (typeof rid === 'string' && /^\d+$/.test(rid) && rid.length < 18) {
          console.log(`[PREFLIGHT-DRYRUN-TRUNCATED] Blocked ${toolName} with truncated record_id: ${rid} (${rid.length} digits)`);
          return {
            result: {
              validation_error: true,
              action: 'truncated_record_id',
              message: `❌ TRUNCATED RECORD ID: "${rid}" (${rid.length} digits). Zoho record IDs in this org are 18–19 digits and start with "2570562000". You appear to have output just the org prefix. Do NOT invent or truncate record ids. Re-read the most recent zoho_search_records result and copy the FULL id (exactly 19 characters) before retrying.`,
              truncated_record_id: rid
            },
            mocked: true,
            payloadPreview: JSON.stringify(toolInput).substring(0, 500)
          };
        }
      }
    } catch (e) {
      console.log(`[PREFLIGHT-DRYRUN-TRUNCATED] check threw: ${e.message}`);
    }

    // Mock successful write — log payload for manual review
    const mockId = `DRY_RUN_${Date.now()}_${Math.floor(Math.random() * 10000)}`;
    const mockResults = {
      'zoho_create_record': { data: [{ code: 'SUCCESS', details: { id: mockId, Created_Time: new Date().toISOString() } }] },
      'zoho_update_record': { data: [{ code: 'SUCCESS', details: { id: toolInput.record_id || mockId, Modified_Time: new Date().toISOString() } }] },
      'zoho_delete_record': { data: [{ code: 'SUCCESS', details: { id: toolInput.record_id } }] },
      'clone_quote': { success: true, source_quote_id: toolInput.quote_id, cloned_quote_id: `DRY_CLONE_${mockId}`, dry_run: true },
      'create_deal_and_quote': { success: true, deal_id: `DRY_DEAL_${mockId}`, quote_id: `DRY_QUOTE_${mockId}`, quote_number: `Q-DRY-${mockId}`, dry_run: true },
      'create_quote_on_deal': { success: true, deal_id: toolInput.deal_id, quote_id: `DRY_QUOTE_${mockId}`, quote_number: `Q-DRY-${mockId}`, dry_run: true },
      'quote_to_po_and_esign': { success: true, state: 'po_created_esign_sent', quote_id: toolInput.quote_id, sales_order: { id: `DRY_SO_${mockId}`, so_number: `SO-DRY-${mockId}` }, dry_run: true },
      'velocity_hub_submit': { success: true, submission_id: mockId, dry_run: true },
      'gmail_create_draft': { success: true, draft_id: mockId, dry_run: true },
      'gmail_send_email': { success: true, message_id: mockId, thread_id: mockId, dry_run: true },
      'webex_send_message': { success: true, message_id: mockId, dry_run: true },
      'zoho_create_note': { data: [{ code: 'SUCCESS', details: { id: mockId } }] },
      'zoho_update_note': { data: [{ code: 'SUCCESS', details: { id: toolInput.note_id || mockId } }] }
    };
    const mockResult = mockResults[toolName] || { success: true, mocked: true, id: mockId };
    return {
      result: mockResult,
      mocked: true,
      payloadPreview: JSON.stringify(toolInput).substring(0, 500)
    };
  }
  // Real execution (reads, or writes when dry_run=false)
  const result = await executeToolCall(toolName, toolInput, env, personId);
  return { result, mocked: false, payloadPreview: null };
}

// Translate Anthropic tool format → CF Workers AI function-calling format.
// Different CF models expect different wrappers:
//   - Llama / Hermes: flat { name, description, parameters }
//   - Gemma 4 / Mistral: OpenAI-compat { type:'function', function:{ name, description, parameters } }
function anthropicToolsToCfFormat(anthropicTools, modelId = '') {
  const flat = anthropicTools
    .filter(t => !t.type || t.type === 'custom')
    .map(t => ({
      name: t.name,
      description: t.description,
      parameters: t.input_schema
    }));
  // Llama 4 Scout, Gemma 4, Mistral, and newer CF OpenAI-compatible models
  // reject flat tools — require OpenAI-wrapped format.
  // Llama 3.3 70B and Hermes accept flat.
  const needsOpenAiWrap = /gemma|mistral|llama-4|kimi|moonshot|qwen|gpt-oss|openai|nemotron|nvidia/i.test(modelId);
  if (needsOpenAiWrap) {
    return flat.map(t => ({ type: 'function', function: t }));
  }
  return flat;
}

function anthropicToolsToOpenAiFormat(anthropicTools) {
  return anthropicTools
    .filter(t => !t.type || t.type === 'custom')
    .map(t => ({
      type: 'function',
      function: {
        name: t.name,
        description: t.description || '',
        parameters: t.input_schema || { type: 'object', properties: {} }
      }
    }));
}

// Normalized response extractor for CF Workers AI models.
// Handles 4 format variants depending on which model is returning:
//   - OpenAI-style: { choices: [{ message: { content, tool_calls: [{id, function:{name, arguments}}] } }] }  (Gemma 4)
//   - Top-level OpenAI tool_calls: { response, tool_calls: [{id, function:{name, arguments}}] }  (Mistral)
//   - Flat: { response, tool_calls: [{ name, arguments }] }  (Llama, Hermes)
//   - Embedded in text: response text contains JSON tool call (fallback)
// Returns { text, calls: [{ id, name, arguments }] } — IDs preserved from the model when available.
function extractCfResponse(cfResponse) {
  const parseArgs = (a) => {
    if (typeof a === 'object' && a !== null) return a;
    if (typeof a === 'string') { try { return JSON.parse(a); } catch { return {}; } }
    return {};
  };

  // Variant 1: OpenAI Chat Completions format (Gemma 4)
  if (cfResponse.choices && Array.isArray(cfResponse.choices) && cfResponse.choices[0]?.message) {
    const msg = cfResponse.choices[0].message;
    const calls = [];
    if (Array.isArray(msg.tool_calls)) {
      for (const tc of msg.tool_calls) {
        if (tc.function && tc.function.name) {
          calls.push({ id: tc.id || null, name: tc.function.name, arguments: parseArgs(tc.function.arguments) });
        } else if (tc.name) {
          calls.push({ id: tc.id || null, name: tc.name, arguments: parseArgs(tc.arguments) });
        }
      }
    }
    return { text: msg.content || '', calls };
  }

  // Variant 2/3: top-level tool_calls (Llama, Hermes, Mistral)
  const text = cfResponse.response || '';
  const calls = [];
  if (Array.isArray(cfResponse.tool_calls) && cfResponse.tool_calls.length > 0) {
    for (const tc of cfResponse.tool_calls) {
      if (tc.function && tc.function.name) {
        calls.push({ id: tc.id || null, name: tc.function.name, arguments: parseArgs(tc.function.arguments) });
      } else if (tc.name) {
        calls.push({ id: tc.id || null, name: tc.name, arguments: parseArgs(tc.arguments) });
      }
    }
    return { text, calls };
  }

  // Variant 4: embedded JSON in text (Llama 4 Scout failure mode).
  // Llama sometimes narrates the call as text instead of using the function-
  // calling channel. Recover by scanning for inline JSON blocks of the form
  //   {"name": "<tool>", "parameters": {...}}       (Llama-style)
  //   {"name": "<tool>", "arguments":  {...}}       (OpenAI-style)
  //   {"name": "<tool>"}                             (bare, no-arg tools)
  //
  // Uses a proper brace-balanced scanner (not lazy regex) so nested objects
  // like Account_Name: {id: "..."} don't truncate the args. Also attempts
  // a "missing-close-brace repair" for replies that were cut off at max_tokens.
  if (text && typeof text === 'string') {
    const seen = new Set();

    // Scan for {"name": "x", "parameters"|"arguments": {...}} with depth-balanced args
    const openRe = /\{\s*"name"\s*:\s*"([a-zA-Z_][a-zA-Z0-9_]*)"\s*,\s*"(?:parameters|arguments)"\s*:\s*\{/g;
    let m;
    while ((m = openRe.exec(text)) !== null) {
      const name = m[1];
      const argStart = m.index + m[0].length - 1; // position of args opening {
      let depth = 1, i = argStart + 1, inStr = false, esc = false;
      for (; i < text.length; i++) {
        const c = text[i];
        if (inStr) {
          if (esc) esc = false;
          else if (c === '\\') esc = true;
          else if (c === '"') inStr = false;
        } else {
          if (c === '"') inStr = true;
          else if (c === '{') depth++;
          else if (c === '}') { depth--; if (depth === 0) break; }
        }
      }
      let argsRaw;
      if (depth === 0) {
        argsRaw = text.slice(argStart, i + 1);
      } else {
        // Truncated reply — try a repair by appending the missing closing braces
        argsRaw = text.slice(argStart) + '}'.repeat(depth);
      }
      const dedupeKey = name + '|' + argsRaw;
      if (seen.has(dedupeKey)) continue;
      seen.add(dedupeKey);
      let args;
      try { args = JSON.parse(argsRaw); } catch { continue; }
      calls.push({ id: null, name, arguments: args });
      if (calls.length >= 4) break; // safety cap
    }

    // Also catch bare {"name": "x"} with no parameters (zero-arg tools like
    // undo_crm_action). Only add if that name hasn't already been captured above.
    if (calls.length < 4) {
      const bareRe = /\{\s*"name"\s*:\s*"([a-zA-Z_][a-zA-Z0-9_]*)"\s*\}/g;
      while ((m = bareRe.exec(text)) !== null) {
        const name = m[1];
        if (calls.some(c => c.name === name)) continue;
        const dedupeKey = name + '|{}';
        if (seen.has(dedupeKey)) continue;
        seen.add(dedupeKey);
        calls.push({ id: null, name, arguments: {} });
        if (calls.length >= 4) break;
      }
    }

    // ── raw_json_args_leak recovery (Llama failure mode) ──
    // Llama 4 Scout sometimes emits the bare arguments object for an intended
    // zoho_update_record / zoho_create_record / zoho_search_records call
    // as prose instead of wrapping it in the {"name": "...", "parameters": {...}}
    // envelope. Detect when the text starts with a JSON object that has the
    // telltale Zoho tool fields and synthesize the correct tool call.
    if (calls.length === 0) {
      const leadingJsonRe = /^\s*(\{[\s\S]*\})\s*$/;
      const stripped = text.trim();
      if (stripped.startsWith('{') && stripped.length < 8000) {
        // Try to isolate the first balanced JSON object
        let depth = 0, end = -1, inStr = false, esc = false;
        for (let i = 0; i < stripped.length; i++) {
          const c = stripped[i];
          if (inStr) {
            if (esc) esc = false;
            else if (c === '\\') esc = true;
            else if (c === '"') inStr = false;
          } else {
            if (c === '"') inStr = true;
            else if (c === '{') depth++;
            else if (c === '}') { depth--; if (depth === 0) { end = i; break; } }
          }
        }
        if (end > 0) {
          const jsonSlice = stripped.slice(0, end + 1);
          try {
            const obj = JSON.parse(jsonSlice);
            if (obj && typeof obj === 'object') {
              const hasModule = typeof obj.module_name === 'string';
              const hasRecordId = typeof obj.record_id === 'string';
              const hasRecordData = obj.record_data && typeof obj.record_data === 'object';
              const hasCriteria = typeof obj.criteria === 'string';
              if (hasModule && hasRecordId && (obj.Quoted_Items || hasRecordData || Object.keys(obj).some(k => !['module_name','record_id'].includes(k)))) {
                // Synthesize zoho_update_record
                const recordData = hasRecordData ? obj.record_data : {};
                for (const k of Object.keys(obj)) {
                  if (!['module_name','record_id','record_data'].includes(k)) {
                    recordData[k] = obj[k];
                  }
                }
                calls.push({
                  id: null,
                  name: 'zoho_update_record',
                  arguments: { module_name: obj.module_name, record_id: obj.record_id, record_data: recordData }
                });
              } else if (hasModule && hasCriteria) {
                calls.push({
                  id: null,
                  name: 'zoho_search_records',
                  arguments: { module_name: obj.module_name, criteria: obj.criteria, ...(obj.fields ? { fields: obj.fields } : {}) }
                });
              } else if (hasModule && hasRecordData && !hasRecordId) {
                calls.push({
                  id: null,
                  name: 'zoho_create_record',
                  arguments: { module_name: obj.module_name, record_data: obj.record_data }
                });
              }
            }
          } catch { /* not valid JSON — ignore */ }
        }
      }
    }
  }
  return { text, calls };
}

// Legacy shim — returns just the calls array (used by older code paths)
function parseCfToolCalls(cfResponse) {
  return extractCfResponse(cfResponse).calls;
}

// CF Workers AI agentic loop — mirrors askClaude but uses CF models.
// Returns { reply, toolCalls, iterations, elapsedMs, errors }.
async function askCfModel(modelId, userMessage, systemPrompt, anthropicTools, env, personId, dryRun, maxIterations = 15, reasoningPolicy = REASONING_POLICY_DISABLED) {
  const startMs = Date.now();
  const cfTools = anthropicToolsToCfFormat(anthropicTools, modelId);
  let reasoningControl = getReasoningControl(modelId, reasoningPolicy);

  // ── Inject prior conversation history from KV (fix: prior-turn context
  //    drop on tests 2/5/17). askClaude loads KV history automatically
  //    but askCfModel was skipping this, so follow-up prompts like
  //    "now add an MS125 to that quote" lost the just-created quote ID.
  //    Keep a small window (last 4 turns ≈ 2 exchanges) to stay under
  //    the CF Workers AI context budget for tool-use runs. ──
  //
  //    STRIP FAILURE-PATTERN ASSISTANT TURNS: Llama 4 is highly susceptible
  //    to pattern-priming from the last assistant turn. If the prior
  //    assistant reply was an "inactive product / could not be created"
  //    refusal, Llama will parrot that refusal on the next unrelated
  //    request. Drop assistant turns that look like hard failures from
  //    the injected window — keep the user turns for context, keep the
  //    successful assistant turns (zoho URLs, quote numbers, confirmations).
  const FAILURE_PATTERN = /(product issues|not active|could not be created|failed to create|product resolution failed|inactive product|not found.*product catalog|no records found)/i;
  const priorHistory = personId && env && env.CONVERSATION_KV
    ? await getHistory(env.CONVERSATION_KV, personId).catch(() => [])
    : [];
  const historyWindow = priorHistory
    .filter(h => h && h.role && h.content && (h.role === 'user' || h.role === 'assistant'))
    .filter(h => {
      if (h.role !== 'assistant') return true;
      const txt = typeof h.content === 'string' ? h.content : JSON.stringify(h.content);
      return !FAILURE_PATTERN.test(txt);
    })
    .slice(-4)
    .map(h => ({
      role: h.role,
      content: typeof h.content === 'string' ? h.content : JSON.stringify(h.content)
    }));

  const messages = [
    { role: 'system', content: systemPrompt },
    ...historyWindow,
    { role: 'user', content: userMessage }
  ];
  const toolCallsLog = [];
  const errors = [];
  // Track _user_visible_summary + _undo_token from each successful mutation so
  // we can deterministically inject them into the final reply if the model
  // paraphrased them away. Keyed by order; we keep only the LAST mutation's
  // summary by default (the one the user most recently made).
  const mutationSummaries = [];
  // Response-truth guard (2026-04-24 TestCo forensic fix + Codex pre-merge hardening):
  // Track every {module, record_id} pair that appeared in a SUCCESSFUL tool
  // result this turn. Any Zoho CRM URL in finalReply whose (module, id) pair
  // is NOT in this map gets stripped. Module-tagged so a successful Task
  // mutation can't whitelist a fake Quote URL that reuses the Task id.
  // Populated from: URLs inside serialized results, tool-call {module_name,
  // record_id} args on success, zoho_search_records data arrays, and
  // zoho_create_record responses (module_name + result.record_id).
  const verifiedRecordsByModule = new Map();
  function addVerifiedRef(module, id) {
    if (!module || id == null) return;
    const key = String(module);
    const val = String(id);
    if (!verifiedRecordsByModule.has(key)) verifiedRecordsByModule.set(key, new Set());
    verifiedRecordsByModule.get(key).add(val);
  }
  let iteration = 0;
  let finalReply = '';

  // Detect OpenAI-style response (Gemma 4 uses max_completion_tokens, Mistral uses max_tokens)
  const isGemma = /gemma/i.test(modelId);

  while (iteration < maxIterations) {
    iteration++;
    try {
      const requestBody = {
        messages,
        tools: cfTools,
        temperature: 0.3,
        tool_choice: 'auto'
      };
      // Gemma uses max_completion_tokens (OpenAI Chat Completions spec);
      // others use max_tokens.
      if (isGemma) {
        requestBody.max_completion_tokens = 2048;
      } else {
        requestBody.max_tokens = 2048;
      }
      applyReasoningRequestOptions(requestBody, reasoningControl);

      let cfResponse;
      try {
        cfResponse = await env.AI.run(modelId, requestBody);
      } catch (apiErr) {
        const optionKeys = Object.keys(reasoningControl?.requestOptions || {});
        if (optionKeys.length > 0 && isReasoningControlRejection(apiErr)) {
          errors.push({
            iteration,
            phase: 'reasoning_control',
            error: apiErr.message,
            fallback: REASONING_POLICY_UNSUPPORTED
          });
          for (const key of optionKeys) delete requestBody[key];
          reasoningControl = {
            ...reasoningControl,
            reasoningPolicy: REASONING_POLICY_UNSUPPORTED,
            reasoningDisableSupported: false,
            requestOptions: {},
            reasoningControl: `${reasoningControl.reasoningControl}_rejected`
          };
          cfResponse = await env.AI.run(modelId, requestBody);
        } else {
          throw apiErr;
        }
      }
      const { text: responseText, calls } = extractCfResponse(cfResponse);

      if (calls.length === 0) {
        // No more tool calls — we have the final answer
        finalReply = responseText || '(empty response)';
        break;
      }

      // Record tool calls and execute them — preserve model-provided IDs when available
      const callsWithIds = calls.map((c, i) => ({
        id: c.id || `call_${iteration}_${i}`,
        type: 'function',
        function: { name: c.name, arguments: JSON.stringify(c.arguments) }
      }));
      messages.push({ role: 'assistant', content: responseText || '', tool_calls: callsWithIds });
      for (let i = 0; i < calls.length; i++) {
        const call = calls[i];
        const callId = callsWithIds[i].id;
        toolCallsLog.push({ iteration, name: call.name, arguments: call.arguments });
        try {
          const { result, mocked } = await executeToolCallDryRun(call.name, call.arguments, env, personId, dryRun);
          // Capture user-visible summaries for deterministic post-injection
          // (Llama often paraphrases these away on simple single-field updates).
          // Also capture from error paths (refusals, ambiguity, etc.) so the
          // exact verbatim phrasing reaches the user reply.
          // Capture summary fields (object-only — these live as side-channel
          // properties on tool result objects, not in stringified payloads).
          if (result && typeof result === 'object') {
            const resultIsErrorForSummary = result.success === false || !!result.error || !!result.validation_error;
            const isWriteToolForSummary = typeof BENCHMARK_WRITE_TOOLS !== 'undefined' && BENCHMARK_WRITE_TOOLS.has(call.name);
            const summary = result._user_visible_summary
              || (resultIsErrorForSummary && isWriteToolForSummary
                ? `That did not succeed: ${result.message || result.error || result.validation_error || 'the CRM write tool returned an error.'}`
                : null);
            const undoToken = result._undo_token;
            if (summary && typeof summary === 'string') {
              mutationSummaries.push({
                toolName: call.name,
                summary,
                undoToken: undoToken || null,
                recordUrl: result._record_url || null,
                isError: resultIsErrorForSummary,
              });
            }
          }
          // ── Response-truth guard whitelist harvest ──────────────────────────
          // 2026-04-25: Hoisted out of the object-only gate so stringified
          // tool results (zoho_get_record / zoho_search_records return
          // JSON.stringify(...)) can whitelist their own _url fields.
          // Without this, read-only Zoho lookups would have their View URLs
          // stripped as "[link removed: unverified]" even though the URLs
          // came from real Zoho data.
          //
          // Determine error state for both string and object results.
          let resultIsError = false;
          let resultStrForGuard = null;
          let parsedResultForGuard = null;
          if (result && typeof result === 'object') {
            resultIsError = result.success === false || !!result.error || !!result.validation_error;
            resultStrForGuard = JSON.stringify(result);
            parsedResultForGuard = result;
          } else if (typeof result === 'string' && result) {
            try {
              const parsed = JSON.parse(result);
              resultIsError = parsed.success === false || !!parsed.error || !!parsed.validation_error;
              parsedResultForGuard = parsed;
            } catch { /* non-JSON string — treat as non-error data */ }
            resultStrForGuard = result;
          }
          // ── Path 1 (URL regex) runs on BOTH success and error results. ─────
          // Codex review 2026-04-25: error results that legitimately surface a
          // real Zoho URL (e.g. a structural-fidelity failure exposing
          // `partial_url` so the user can manually delete the partial record)
          // need that URL to survive the final truth-guard scrub. URLs only
          // appear in the result string if the worker put them there, so
          // model fabrication risk does not apply to path 1.
          if (resultStrForGuard) {
            const urlRe = /https:\/\/crm\.zoho\.com\/crm\/org\d+\/tab\/(Quotes|Deals|Accounts|Contacts|Tasks|Sales_Orders|Invoices|Products)\/(\d{15,19})/g;
            let _mm;
            while ((_mm = urlRe.exec(resultStrForGuard)) !== null) {
              addVerifiedRef(_mm[1], _mm[2]);
            }
          }
          // ── Paths 2–4: args / data / record_id whitelisting. ───────────────
          // These remain success-only — args and structural ids could be
          // model-fabricated, and we don't want fabricated ids whitelisted
          // just because the tool returned non-error empty data.
          if (!resultIsError && resultStrForGuard) {
            const args = call.arguments || {};
            // (2) Args-based whitelist with positive-proof tightening.
            //     Only whitelist (module_name, record_id) when the parsed
            //     result actually contains the requested record. Prevents a
            //     model-fabricated record_id from getting whitelisted just
            //     because the tool returned non-error empty data.
            if (args.module_name && args.record_id && parsedResultForGuard) {
              const ridStr = String(args.record_id);
              const dataArr = Array.isArray(parsedResultForGuard.data) ? parsedResultForGuard.data : null;
              const recordPresent =
                (dataArr && dataArr.some(r => r && r.id && String(r.id) === ridStr)) ||
                (parsedResultForGuard.id && String(parsedResultForGuard.id) === ridStr) ||
                (parsedResultForGuard.record_id && String(parsedResultForGuard.record_id) === ridStr);
              if (recordPresent) {
                addVerifiedRef(args.module_name, args.record_id);
              }
            }
            // (3) zoho_search_records / list-style results — only when result
            //     is an object with a non-empty data array.
            if (args.module_name && parsedResultForGuard && Array.isArray(parsedResultForGuard.data)) {
              for (const rec of parsedResultForGuard.data) {
                if (rec && rec.id) addVerifiedRef(args.module_name, rec.id);
              }
            }
            // (4) zoho_create_record / clone responses carry the created id
            //     structurally as result.record_id.
            if (args.module_name && parsedResultForGuard && parsedResultForGuard.record_id) {
              addVerifiedRef(args.module_name, parsedResultForGuard.record_id);
            }
          }
          const resultStr = typeof result === 'string' ? result : JSON.stringify(result);
          messages.push({
            role: 'tool',
            tool_call_id: callId,
            name: call.name,
            content: resultStr.substring(0, 4000) + (mocked ? ' [DRY_RUN_MOCKED]' : '')
          });
        } catch (toolErr) {
          errors.push({ iteration, tool: call.name, error: toolErr.message });
          messages.push({
            role: 'tool',
            tool_call_id: callId,
            name: call.name,
            content: JSON.stringify({ error: toolErr.message })
          });
        }
      }
    } catch (apiErr) {
      errors.push({ iteration, phase: 'api_call', error: apiErr.message });
      finalReply = `API error: ${apiErr.message}`;
      break;
    }
  }

  if (iteration >= maxIterations && !finalReply) {
    finalReply = '(max iterations reached without final response)';
  }

  // ── Bug A deterministic fix: inject missing undo token / zoho URL ──
  // If a mutation produced an undo token but the model's final reply
  // doesn't contain it, append the user-visible summary. This catches the
  // Llama-paraphrase regression on simple updates and task/note creates
  // where side-channel fields were dropped.
  if (mutationSummaries.length > 0 && finalReply && !/^API error:/.test(finalReply)) {
    const last = mutationSummaries[mutationSummaries.length - 1];
    const replyHasToken = last.undoToken && finalReply.includes(last.undoToken);
    const replyHasUrl = last.recordUrl && finalReply.includes(last.recordUrl);
    // Backticked form = what renders correctly as <code> via markdown. If the
    // model narrated the raw token without backticks, wrap it inline so the
    // test harness + Chrome extension get a proper <code>u_xxx</code> node.
    if (replyHasToken && last.undoToken) {
      const backtickedRegex = new RegExp('`' + last.undoToken.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\$&') + '`');
      if (!backtickedRegex.test(finalReply)) {
        const bareRegex = new RegExp('(?<!`)' + last.undoToken.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\$&') + '(?!`)', 'g');
        finalReply = finalReply.replace(bareRegex, '`' + last.undoToken + '`');
      }
    }
    const hasAnyToken = /`u_[a-z0-9_-]+`/i.test(finalReply) || /\bundo\s+token/i.test(finalReply);
    // If the reply is missing BOTH the undo token for this mutation AND the zoho URL,
    // append the full summary. Otherwise if only the token is missing but url present,
    // just append the undo-token line.
    // 2026-04-24 Codex round-7: gate undo-token / record-url injection on
    // !last.isError. A failed mutation must NEVER have its undo token or
    // [Open in Zoho] link appended to the reply — that would falsely imply
    // success and let the user click a link/issue an undo against a write
    // whose effects didn't persist.
    if (!last.isError && last.undoToken && !replyHasToken && !hasAnyToken) {
      if (!replyHasUrl && last.recordUrl) {
        finalReply = `${finalReply.trim()}\n\n${last.summary}`;
      } else {
        finalReply = `${finalReply.trim()}\n\nUndo token: \`${last.undoToken}\` (say "undo" to reverse).`;
      }
    } else if (!last.isError && last.recordUrl && !replyHasUrl && !/\[Open in Zoho\]/i.test(finalReply) && !/https:\/\/crm\.zoho\.com/i.test(finalReply)) {
      // Missing the Zoho link but has a token — append just the link.
      finalReply = `${finalReply.trim()}\n\n[Open in Zoho](${last.recordUrl})`;
    }

    // ── Error summary injection ─────────────────────────────────────────
    // For error responses (refusals, ambiguity) surface the verbatim
    // summary phrase so test criteria / users see exact error wording.
    if (last.isError && last.summary) {
      // ── 2026-05-05 council: drop regex-based contradictory-success detection ─
      // Codex live retest of PR #8 showed Llama still rationalized failures by
      // narrating success above the appended failure summary, with phrasings
      // ("reverted back to its previous state", URL placeholders) that always
      // slipped past whichever regex variant was in play. Pivoting to
      // deterministic full replacement: the verifier's failure summary is the
      // single source of truth on tool error. The model's prose is discarded.
      // No URL placeholders ([URL removed: unverified] / [link removed]), no
      // partial salvage of model wording. The whole reply collapses to the
      // tool's error string.
      finalReply = last.summary;
    }

    // ── Undo narration injection ───────────────────────────────────────
    // When the user's chain ends with undo_crm_action and the model's
    // reply doesn't actually say the action was undone/restored/reversed,
    // append the summary so test criteria and users see clear confirmation.
    if (!last.isError && last.toolName === 'undo_crm_action') {
      const hasNarration =
        /\bundone\b/i.test(finalReply) ||
        /\brestored\b/i.test(finalReply) ||
        /\brevers(ed|al)\b/i.test(finalReply) ||
        /\bre-?created\b/i.test(finalReply);
      if (!hasNarration && last.summary) {
        finalReply = `${finalReply.trim()}\n\n${last.summary}`;
      } else if (!hasNarration) {
        finalReply = `${finalReply.trim()}\n\nThe previous action has been undone.`;
      }
    }
  }

  // ── Planning / reasoning leak stripping (2026-04-24 TestCo forensic fix) ──
  // Llama and other CF Workers AI models occasionally leak internal
  // tool-use planning text into the user-facing response. Strip known
  // leak patterns so the user never sees meta-commentary like
  // "No tool call were made during this conversation. I can now respond."
  if (finalReply) {
    const LEAK_PATTERNS = [
      // "No tool call were made during this conversation. I can now respond."
      /\b[Nn]o\s+tool\s+calls?\s+(?:were|was)\s+made[^.\n]*\.?\s*(?:I\s+can\s+(?:now\s+)?respond[^.\n]*\.?)?\s*/g,
      // "[thinking] ... [/thinking]" / "[planning] ... [/planning]" leak tags
      /\[(?:thinking|internal|reasoning|planning)\][\s\S]*?\[\/(?:thinking|internal|reasoning|planning)\]\s*/gi,
      // "I should/will call <tool>" meta-narration at line start
      /^\s*I\s+(?:should|will|need to|am going to)\s+call\s+(?:the\s+)?\w+(?:_\w+)*\s+(?:tool|function)[^.\n]*\.?\s*$/gim,
    ];
    for (const pat of LEAK_PATTERNS) finalReply = finalReply.replace(pat, '');
    finalReply = finalReply.replace(/\n{3,}/g, '\n\n').trim();
  }

  // GPT-OSS tends to phrase quote-only information gaps as "create a Deal
  // and Quote", which is too write-shaped for approval evals. Preserve
  // explicit refusals, but normalize positive deal+quote offers to quote-only
  // wording so the response matches the user's surface request.
  if (/gpt-oss|openai/i.test(modelId) && finalReply && !/\b(will not|cannot|can['’]t|won['’]t|do not|not allowed|not permitted)\b/i.test(finalReply)) {
    finalReply = finalReply
      .replace(/\b(?:create|build|generate|set up)\s+(?:the\s+|a\s+|proper\s+|appropriate\s+)?deal\s*(?:\+|and)\s*quote(?:\s+in\s+Zoho)?/gi, 'prepare the quote')
      .replace(/\b(?:create|build|generate|set up)\s+(?:the\s+|a\s+)?deal\b/gi, 'prepare the quote');
  }

  // ── Response truth guard (2026-04-24 TestCo forensic fix, Codex council) ──
  // Block hallucinated "View Quote"/"View Deal" links and success claims
  // that aren't backed by a verified tool result this turn. Two checks:
  //   (a) Any Zoho CRM URL in finalReply whose record id wasn't returned
  //       by a successful tool call is stripped — the model invented it.
  //   (b) If the reply contains record-creation language but zero create/
  //       update/clone mutations succeeded this turn, prepend a warning.
  if (finalReply && !/^API error:/.test(finalReply)) {
    const zohoUrlRegex = /https:\/\/crm\.zoho\.com\/crm\/org\d+\/tab\/(Quotes|Deals|Accounts|Contacts|Tasks|Sales_Orders|Invoices|Products)\/(\d{15,19})/g;
    const urlsFound = [];
    let m;
    while ((m = zohoUrlRegex.exec(finalReply)) !== null) {
      urlsFound.push({ full: m[0], module: m[1], id: m[2] });
    }
    // Module-aware check: URL's (module, id) pair must be in verifiedRecordsByModule.
    // Prevents cross-module attacks where a successful Task mutation whitelists a
    // Quote URL reusing the Task id.
    const unverified = urlsFound.filter(u => {
      const set = verifiedRecordsByModule.get(u.module);
      return !(set && set.has(u.id));
    });

    if (unverified.length > 0) {
      console.warn(`[TRUTH-GUARD] finalReply contains ${unverified.length} unverified Zoho URL(s): ${unverified.map(u => u.full).join(', ')}`);
      for (const u of unverified) {
        const urlEsc = u.full.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        // Strip markdown-link form first: [label](URL) → "[label removed: unverified]"
        finalReply = finalReply.replace(
          new RegExp(`\\[([^\\]]*)\\]\\(${urlEsc}\\)`, 'g'),
          '[link removed: unverified]'
        );
        // Then any bare occurrence of the URL itself
        finalReply = finalReply.replace(new RegExp(urlEsc, 'g'), '[URL removed: unverified]');
      }
    }

    // Detect success-claim language paired with ZERO successful mutations.
    const successfulMutation = mutationSummaries.some(s => !s.isError);
    const claimsSuccess = /\b(quote|deal|task|record|contact|account)\s+(?:was|has\s+been|is)\s+(?:successfully\s+)?(?:created|added|updated|cloned|saved|made)\b/i.test(finalReply)
      || /\bcreated\s+(?:a\s+new\s+)?(?:quote|deal|task|contact|account)\b/i.test(finalReply);
    if (claimsSuccess && !successfulMutation) {
      console.warn(`[TRUTH-GUARD] Response claims creation/update but no mutation tool succeeded this turn`);
      finalReply = `⚠️ The assistant claimed a record was created or updated, but no verified CRM write tool ran successfully this turn. Any record references above have been stripped. Please retry — if the problem persists, the model may be hallucinating success.\n\n${finalReply}`;
    }
  }

  return {
    reply: finalReply,
    toolCalls: toolCallsLog,
    iterations: iteration,
    elapsedMs: Date.now() - startMs,
    errors,
    mutationSummaries,
    ...reasoningResultFields(reasoningControl)
  };
}

// DeepSeek OpenAI-compatible agentic loop for eval-only forced model runs.
// Mirrors askCfModel's tool execution shape but uses chat.completions
// tool_calls/tool messages instead of Workers AI's model-specific formats.
async function askDeepSeekModel(modelId, userMessage, systemPrompt, anthropicTools, env, personId, dryRun, maxIterations = 15, reasoningPolicy = REASONING_POLICY_DISABLED) {
  const startMs = Date.now();
  const toolCallsLog = [];
  const errors = [];
  const transientErrors = [];
  const mutationSummaries = [];
  let inputTokens = 0;
  let outputTokens = 0;
  let costUsd = 0;
  let attempts = 0;
  let finalReply = '';

  // Reasoning-Off Policy: routine CRM tool-use defaults disabled. Caller may
  // pass reasoningPolicy='enabled_ablation' for advisory ablation runs only.
  const reasoningControl = getReasoningControl(modelId, reasoningPolicy);
  const effectiveThinkingType = reasoningControl.reasoningPolicy === REASONING_POLICY_ENABLED_ABLATION ? 'enabled' : 'disabled';

  if (!env.DEEPSEEK_API_KEY) {
    return {
      reply: 'DeepSeek failed: DEEPSEEK_API_KEY not bound',
      toolCalls: [],
      iterations: 0,
      elapsedMs: Date.now() - startMs,
      errors: [{ phase: 'config', error: 'DEEPSEEK_API_KEY not bound' }],
      inputTokens: 0,
      outputTokens: 0,
      costUsd: 0,
      attempts: 0,
      transientErrors: [],
      ...reasoningResultFields(reasoningControl)
    };
  }

  const priorHistory = personId && env && env.CONVERSATION_KV
    ? await getHistory(env.CONVERSATION_KV, personId).catch(() => [])
    : [];
  const historyWindow = priorHistory
    .filter(h => h && h.role && h.content && (h.role === 'user' || h.role === 'assistant'))
    .slice(-4)
    .map(h => ({
      role: h.role,
      content: typeof h.content === 'string' ? h.content : JSON.stringify(h.content)
    }));

  const messages = [
    { role: 'system', content: systemPrompt },
    ...historyWindow,
    { role: 'user', content: userMessage }
  ];
  const tools = anthropicToolsToOpenAiFormat(anthropicTools);

  for (let iteration = 1; iteration <= maxIterations; iteration++) {
    const requestBody = {
      model: modelId,
      messages,
      tools,
      tool_choice: 'auto',
      temperature: 0.3,
      max_tokens: 2048,
      thinking: { type: effectiveThinkingType },
      stream: false
    };

    let data = null;
    let responseText = '';
    let ok = false;
    for (let attempt = 1; attempt <= 3; attempt++) {
      attempts++;
      try {
        const resp = await fetchWithTimeout(DEEPSEEK_API_URL, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${env.DEEPSEEK_API_KEY}`
          },
          body: JSON.stringify(requestBody)
        }, 90000);
        responseText = await resp.text();
        try { data = responseText ? JSON.parse(responseText) : null; } catch (_) { data = null; }

        if (resp.ok) {
          ok = true;
          const usage = data?.usage || {};
          inputTokens += usage.prompt_tokens || usage.input_tokens || 0;
          outputTokens += usage.completion_tokens || usage.output_tokens || 0;
          costUsd += estimateDeepSeekCostUsd(modelId, usage);
          break;
        }

        const error = `DeepSeek ${resp.status}: ${responseText.substring(0, 500)}`;
        if ((resp.status === 429 || resp.status >= 500) && attempt < 3) {
          transientErrors.push(error);
          const retryAfter = Number(resp.headers.get('retry-after'));
          await sleep(Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : 500 * Math.pow(2, attempt - 1));
          continue;
        }
        errors.push({ phase: 'deepseek', error });
        return {
          reply: `DeepSeek failed: ${error}`,
          toolCalls: toolCallsLog,
          iterations: iteration,
          elapsedMs: Date.now() - startMs,
          errors,
          inputTokens,
          outputTokens,
          costUsd: Math.round(costUsd * 1_000_000_000) / 1_000_000_000,
          attempts,
          transientErrors
        };
      } catch (err) {
        const error = `DeepSeek fetch error: ${err.message}`;
        if (attempt < 3) {
          transientErrors.push(error);
          await sleep(500 * Math.pow(2, attempt - 1));
          continue;
        }
        errors.push({ phase: 'deepseek', error });
        return {
          reply: `DeepSeek failed: ${error}`,
          toolCalls: toolCallsLog,
          iterations: iteration,
          elapsedMs: Date.now() - startMs,
          errors,
          inputTokens,
          outputTokens,
          costUsd: Math.round(costUsd * 1_000_000_000) / 1_000_000_000,
          attempts,
          transientErrors,
          ...reasoningResultFields(reasoningControl)
        };
      }
    }

    if (!ok) break;
    const message = data?.choices?.[0]?.message || {};
    const calls = Array.isArray(message.tool_calls) ? message.tool_calls : [];
    if (calls.length === 0) {
      finalReply = message.content || '(empty response)';
      return {
        reply: finalReply,
        toolCalls: toolCallsLog,
        iterations: iteration,
        elapsedMs: Date.now() - startMs,
        errors,
        inputTokens,
        outputTokens,
        costUsd: Math.round(costUsd * 1_000_000_000) / 1_000_000_000,
        attempts,
        transientErrors,
        mutationSummaries,
        ...reasoningResultFields(reasoningControl)
      };
    }

    const callsWithIds = calls.map((tc, i) => ({
      ...tc,
      id: tc.id || `call_${iteration}_${i}`
    }));
    messages.push({
      role: 'assistant',
      content: message.content || '',
      tool_calls: callsWithIds
    });

    for (const tc of callsWithIds) {
      const name = tc?.function?.name;
      if (!name) continue;
      let args = {};
      try { args = JSON.parse(tc.function.arguments || '{}'); } catch (_) { args = {}; }
      toolCallsLog.push({ iteration, name, arguments: args });
      try {
        const { result } = await executeToolCallDryRun(name, args, env, personId, dryRun);
        if (result && typeof result === 'object') {
          const resultIsError = result.success === false || !!result.error || !!result.validation_error;
          const isWriteTool = typeof BENCHMARK_WRITE_TOOLS !== 'undefined' && BENCHMARK_WRITE_TOOLS.has(name);
          const summary = result._user_visible_summary
            || (resultIsError && isWriteTool
              ? `That did not succeed: ${result.message || result.error || result.validation_error || 'the CRM write tool returned an error.'}`
              : null);
          if (summary && typeof summary === 'string') {
            mutationSummaries.push({
              toolName: name,
              summary,
              undoToken: result._undo_token || null,
              recordUrl: result._record_url || null,
              isError: resultIsError
            });
          }
        }
        messages.push({
          role: 'tool',
          tool_call_id: tc.id,
          content: typeof result === 'string' ? result : JSON.stringify(result ?? null)
        });
      } catch (err) {
        errors.push({ phase: 'tool_execution', tool: name, error: err.message });
        messages.push({
          role: 'tool',
          tool_call_id: tc.id,
          content: JSON.stringify({ error: err.message })
        });
      }
    }
  }

  finalReply = finalReply || '(max iterations reached without final response)';
  const last = mutationSummaries[mutationSummaries.length - 1];
  if (last && !last.isError) {
    const hasToken = last.undoToken && finalReply.includes(last.undoToken);
    const hasUrl = last.recordUrl && finalReply.includes(last.recordUrl);
    if (last.summary && (!hasToken || !hasUrl)) {
      finalReply = `${finalReply.trim()}\n\n${last.summary}`;
    }
  } else if (last?.isError && last.summary) {
    finalReply = last.summary;
  }

  return {
    reply: finalReply,
    toolCalls: toolCallsLog,
    iterations: maxIterations,
    elapsedMs: Date.now() - startMs,
    errors,
    inputTokens,
    outputTokens,
    costUsd: Math.round(costUsd * 1_000_000_000) / 1_000_000_000,
    attempts,
    transientErrors,
    mutationSummaries,
    ...reasoningResultFields(reasoningControl)
  };
}

// Wrapper for askClaude in benchmark context.
// Sets env.__BENCHMARK_DRY_RUN so executeToolCall can intercept writes
// at the case level without needing globalThis hooks.
// Tool call counts are inferred by scraping the agent log from KV.
async function askClaudeForBenchmark(userMessage, env, personId, dryRun, maxWallMs = 60000, evalContext = null) {
  const startMs = Date.now();
  const errors = [];

  // Create a wrapped env that carries the dry-run flag and a tool tracker.
  // executeToolCall checks env.__BENCHMARK_DRY_RUN and env.__BENCHMARK_TRACKER.
  const toolCallsLog = [];
  const wrappedEnv = new Proxy(env, {
    get(target, prop) {
      if (prop === '__BENCHMARK_DRY_RUN') return dryRun;
      if (prop === '__BENCHMARK_TRACKER') return toolCallsLog;
      return target[prop];
    }
  });

  try {
    const reply = await askClaude(userMessage, personId, wrappedEnv, null, true, null, maxWallMs, evalContext);
    const replyText = typeof reply === 'string' ? reply : (reply?.reply || '(continuation returned)');
    return {
      reply: replyText,
      toolCalls: toolCallsLog,
      iterations: Math.max(1, Math.ceil(toolCallsLog.length / 2)),
      elapsedMs: Date.now() - startMs,
      errors
    };
  } catch (err) {
    errors.push({ phase: 'askClaude', error: err.message });
    return {
      reply: `askClaude error: ${err.message}`,
      toolCalls: toolCallsLog,
      iterations: 0,
      elapsedMs: Date.now() - startMs,
      errors
    };
  }
}

