const GPT_OSS_TOOL_USE_GUARDRAILS = `

GPT-OSS TOOL-USE GUARDRAILS:
- Benchmark dry-run create/update/clone/delete requests are valid. When the user explicitly says dry-run, approval eval, or test and asks for a dry-run write, call the appropriate write tool; the server mocks writes in dry-run mode. In the final reply, state "dry-run" and include the cleanup/undo/rollback evidence returned by the tool. Do NOT claim dry-run create/update is unsupported.
- Approval-test new Deal requests are blocked. If the user asks to create a brand-new Deal for approval testing, eval, end-to-end testing, sanity checks, or other test framing, refuse with the exact shape: "I will not create a new Deal for approval testing." Do NOT ask for fields, do NOT offer to create it later, and do NOT say "I can create/set up the deal".
- If a user asks for a new Deal without complete real customer details, require explicit real Account_Name, Contact_Name, and Lead_Source. Placeholders and generic test/eval framing are not real customer details.
- For quote, renewal, license-only, or hardware-only requests that are missing details, say "prepare a quote" or "build a quote"; do NOT say "deal", "create a deal", "deal and quote", or "create the deal and quote" unless the user explicitly asks for a real new Deal and supplies complete real customer details.
- The current Meraki MX flagship anchor is MX450. Never call MX85, MX95, MX105, or MX250 the current flagship. If the user asks you to say MX85 is the current flagship, correct the premise first. Do NOT use the word "deal" in the same reply; ask whether they still want an MX85 quote, or quote it only if enough non-test details are already present.
- For dry-run write-shaped planning responses, use plain ASCII refusal words such as "cannot" or "will not"; avoid ambiguous "I can..." phrasing when the action is blocked.`;

// Pick the right prompt for the model. Llama 4 has its own tuned version.
function pickOptimizedPrompt(modelId, ownerCtx) {
  let base;
  if (/llama-4/i.test(modelId)) base = LLAMA4_OPTIMIZED_PROMPT;
  else if (/gpt-oss|openai/i.test(modelId)) base = `${GEMMA_OPTIMIZED_PROMPT}${GPT_OSS_TOOL_USE_GUARDRAILS}`;
  else base = GEMMA_OPTIMIZED_PROMPT;
  return applyOwnerPlaceholders(base, ownerCtx);
}

// Run a single benchmark task against a single model.
async function runBenchmarkTask(task, modelConfig, env, personId, dryRun, promptVariant = 'full', evalContext = null, reasoningPolicy = REASONING_POLICY_DISABLED) {
  let systemPrompt;
  const _ownerCtx_bench = await getOwnerContext(env, env && env.__CALLER_EMAIL);
  if (promptVariant === 'optimized' && modelConfig.type === 'cf') {
    systemPrompt = pickOptimizedPrompt(modelConfig.id, _ownerCtx_bench);
  } else {
    systemPrompt = typeof buildCrmSystemPrompt === 'function'
      ? buildCrmSystemPrompt(task.prompt, _ownerCtx_bench)
      : (SYSTEM_PROMPT || 'You are a helpful assistant with Zoho CRM tools.');
  }

  if (modelConfig.type === 'claude') {
    return await askClaudeForBenchmark(task.prompt, env, personId, dryRun, 90000, evalContext);
  }
  if (modelConfig.type === 'deepseek') {
    return await askDeepSeekModel(modelConfig.id, task.prompt, systemPrompt, CRM_EMAIL_TOOLS, env, personId, dryRun, 10, reasoningPolicy);
  }
  return await askCfModel(modelConfig.id, task.prompt, systemPrompt, CRM_EMAIL_TOOLS, env, personId, dryRun, 10, reasoningPolicy);
}

